CREATE TABLE "TransportistasTerceros" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_TransportistasTerceros" PRIMARY KEY,
    "RazonSocial" character varying(200) NOT NULL,
    "DocumentoFiscal" character varying(30) NOT NULL,
    "Pais" character varying(100) NOT NULL,
    "TipoServicio" character varying(10) NOT NULL,
    "Contacto" character varying(100),
    "Email" character varying(150),
    "Telefono" character varying(20),
    "Observaciones" character varying(500),
    "Activo" boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "CK_TransportistasTerceros_Textos" CHECK (btrim("RazonSocial") <> '' AND btrim("DocumentoFiscal") <> '' AND btrim("Pais") <> ''),
    CONSTRAINT "CK_TransportistasTerceros_TipoServicio" CHECK ("TipoServicio" IN ('3PL', 'Flete', 'Ambos'))
);
CREATE UNIQUE INDEX "IX_TransportistasTerceros_PaisDocumentoNormalizados"
    ON "TransportistasTerceros" (lower(btrim("Pais")), lower(btrim("DocumentoFiscal")));

CREATE TABLE "FletesTerceros" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_FletesTerceros" PRIMARY KEY,
    "TransportistaTerceroId" integer NOT NULL,
    "Referencia" character varying(30) NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    "Origen" character varying(120) NOT NULL,
    "Destino" character varying(120) NOT NULL,
    "Importe" numeric(18,2) NOT NULL,
    "Moneda" character varying(3) NOT NULL,
    "Estado" character varying(15) NOT NULL DEFAULT 'Registrado',
    "Observaciones" character varying(500),
    "MotivoCancelacion" character varying(500),
    "FechaCancelacion" timestamp with time zone,
    CONSTRAINT "FK_FletesTerceros_TransportistasTerceros" FOREIGN KEY ("TransportistaTerceroId") REFERENCES "TransportistasTerceros" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_FletesTerceros_Textos" CHECK (btrim("Referencia") <> '' AND btrim("Origen") <> '' AND btrim("Destino") <> ''),
    CONSTRAINT "CK_FletesTerceros_Importe" CHECK ("Importe" > 0),
    CONSTRAINT "CK_FletesTerceros_Moneda" CHECK ("Moneda" ~ '^[A-Z]{3}$'),
    CONSTRAINT "CK_FletesTerceros_Estado" CHECK (
        ("Estado" = 'Registrado' AND "MotivoCancelacion" IS NULL AND "FechaCancelacion" IS NULL)
        OR ("Estado" = 'Cancelado' AND btrim(coalesce("MotivoCancelacion", '')) <> '' AND "FechaCancelacion" IS NOT NULL))
);
CREATE INDEX "IX_FletesTerceros_TransportistaTerceroId" ON "FletesTerceros" ("TransportistaTerceroId");
CREATE INDEX "IX_FletesTerceros_FechaId" ON "FletesTerceros" ("Fecha" DESC, "Id" DESC);
CREATE UNIQUE INDEX "IX_FletesTerceros_TransportistaReferenciaNormalizada"
    ON "FletesTerceros" ("TransportistaTerceroId", lower(btrim("Referencia")));
